for (const l of LANGS) for (const [k, v] of Object.entries(ICONS[l])) S[l]['icon.' + k] = v;

let lang = 'ru';
export function initI18n(preferred) {
  const sys = (navigator.language || 'ru').slice(0, 2);
  lang = [preferred, sys].find((l) => LANGS.includes(l)) || 'ru';
  document.documentElement.lang = lang;
  return lang;
}
export const getLang = () => lang;

// t(key, { name }) — строка с подстановкой; fallback — если ключа нет нигде (иначе — сам ключ)
export function t(key, vars, fallback) {
  const s = S[lang]?.[key] ?? S.ru[key] ?? fallback ?? key;
  return vars ? String(s).replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m)) : s;
}
export const STRINGS = S;
